<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useWorkforce} from '../context'
import {useWorkforceText} from '../text'
import type {Administrator} from '../types'
const {api,home,store,current}=useWorkforce(),route=useRoute(),router=useRouter(),{t,error}=useWorkforceText(),items=ref<Administrator[]>([]),account=ref(String(route.query.account||'')),employeeManage=ref(true),payrollCompanyId=ref<string|null>(null),version=ref(0),loading=ref(true),busy=ref(false),failure=ref('')
function select(){const old=items.value.find(a=>a.accountId===account.value);employeeManage.value=old?.employeeManage??true;payrollCompanyId.value=old?.payrollCompanyId??null;version.value=old?.version??0}
onMounted(async()=>{if(!home.value?.headOffice){loading.value=false;return}try{const data=await api().get<Administrator[]>('/administrators');if(current()){items.value=data;select()}}catch(e){if(current())failure.value=error(e)}finally{if(current())loading.value=false}})
async function save(){if(!account.value||busy.value)return;busy.value=true;failure.value='';try{await api().put(`/administrators/${account.value}`,{expectedVersion:version.value,employeeManage:employeeManage.value,payrollCompanyId:payrollCompanyId.value});if(current())await router.push(`/stores/${store.value}/workforce/administrators`)}catch(e){if(current())failure.value=error(e)}finally{if(current())busy.value=false}}
</script>
<template><section class="wf-panel wf-form-panel"><h2>{{t('grant')}}</h2><p v-if="failure" role="alert" class="wf-error">{{failure}}</p><p v-if="loading" role="status">{{t('loading')}}</p><form v-else-if="home?.headOffice" @submit.prevent="save"><fieldset :disabled="busy"><label>{{t('administrator')}}<select v-model="account" required @change="select"><option value="" disabled>{{t('select')}}</option><option v-for="a in home.administratorAccounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label class="wf-check"><input v-model="employeeManage" type="checkbox">{{t('employeeManage')}}</label><label>{{t('payrollCompany')}}<select v-model="payrollCompanyId"><option :value="null">{{t('payrollOff')}}</option><option v-for="c in home.companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><p class="wf-hint">{{t('grantHint')}}</p></fieldset><footer class="wf-form-actions"><RouterLink class="wf-button" :to="`/stores/${store}/workforce/administrators`">{{t('cancel')}}</RouterLink><button class="primary" :disabled="busy">{{t(busy?'saving':'save')}}</button></footer></form><p v-else role="alert">{{t('noAccess')}}</p></section></template>
